from sys import stdin
T = 1
T = int(stdin.readline())
for _ in range(T):
	(m, x, y) = map(int, stdin.readline().split())
	a = 1
	b = 2
	for i in range(2, int(m / 2 + 1)):
		mark = int(i * x / y)
		if a < mark + 1:
			a = 2 * a - 1
		elif a < i:
			a = 2 * a + 1
		elif a < mark + i:
			a = 2 * (a - i + 1)
		else:
			a = 2 * (a - i + 2)
		if b < mark + 1:
			b = 2 * b - 1
		elif b < i:
			b = 2 * b + 1
		elif b < mark + i:
			b = 2 * (b - i + 1)
		else:
			b = 2 * (b - i + 2)
	print(a ^ b)
